type FfiConverterTransactionBuilder struct {}

var FfiConverterTransactionBuilderINSTANCE = FfiConverterTransactionBuilder{}


func (c FfiConverterTransactionBuilder) Lift(handle C.uint64_t) *TransactionBuilder {
	result := &TransactionBuilder {
		newFfiObject(
			handle,
			func(handle C.uint64_t, status *C.RustCallStatus) C.uint64_t {
				return C.uniffi_iota_sdk_ffi_fn_clone_transactionbuilder(handle, status)
			},
			func(handle C.uint64_t, status *C.RustCallStatus) {
				C.uniffi_iota_sdk_ffi_fn_free_transactionbuilder(handle, status)
			},
		),
	}
	runtime.SetFinalizer(result, (*TransactionBuilder).Destroy)
	return result
}

func (c FfiConverterTransactionBuilder) Read(reader io.Reader) *TransactionBuilder {
	return c.Lift(C.uint64_t(readUint64(reader)))
}

func (c FfiConverterTransactionBuilder) Lower(value *TransactionBuilder) C.uint64_t {
	// TODO: this is bad - all synchronization from ObjectRuntime.go is discarded here,
	// because the handle will be decremented immediately after this function returns,
	// and someone will be left holding onto a non-locked handle.
	handle := value.ffiObject.incrementPointer("*TransactionBuilder")
	defer value.ffiObject.decrementPointer()
	return handle
}

func (c FfiConverterTransactionBuilder) Write(writer io.Writer, value *TransactionBuilder) {
	writeUint64(writer, uint64(c.Lower(value)))
}

func LiftFromExternalTransactionBuilder(handle uint64) *TransactionBuilder {
	return FfiConverterTransactionBuilderINSTANCE.Lift(C.uint64_t(handle))
}

func LowerToExternalTransactionBuilder(value *TransactionBuilder) uint64 {
	return uint64(FfiConverterTransactionBuilderINSTANCE.Lower(value))
}

